head.script:


///////// 1. 변수 및 선언 영역 /////////
scwin.storageId = "";

// 파라미터 임시 저장소

///////// 2. 초기화 영역 /////////
            scwin.onpageload = function () {

                scwin.vScrenID = "ULDTMS03020.xml";
                scwin.storageId = $c.data.getParameter("storageId");
                const formCd = $c.data.getParameter("formCd");
                const formVer = $c.data.getParameter("formVer");                

                dma_search.set("formCd", formCd);
                dma_search.set("formVer", formVer);

                // 상세 조회                
                scwin.fnSearch();
            };

///////// 3. 컴포넌트 이벤트 영역 /////////
            scwin.sbx_formVer_onchange = function (info) {

                dma_search.set("formVer", info.newValue);
                // 조회
                scwin.fnSearch();
            };

            scwin.btn_list_onclick = function (e) {

                let params = {};
                if (scwin.storageId !== "") {
                    params.storageId = scwin.storageId;
                }
                const url_ = "/ui/TMS/ULDTMS03010.xml";
                $c.win.moveUrl(url_, params);
            };

            scwin.grid_list1_oncellclick = async function (rowIndex, columnIndex, columnId) {

                const params = {};
                if (columnId === "button1") {                    
                    params.formCd = dlt_list1.getCellData(rowIndex, "formCd");
                    params.formKorNm = dma_result.get("formKorNm");
                    params.formVer = dlt_list1.getCellData(rowIndex, "formVer");
                    params.storageId = "";

                    const url_ = "/ui/TMS/ULDTMS03180.xml";
                	const options = {
                    	id: "ULDTMS03180_POP",
                    	popupName: "기재상의 주의 관리 상세",
                    	width: "600",
                    	height: "320",
                    	frameModal: "top"
                	};
                    const result = await $c.win.openPopup(url_, options, params);
                    if (!$c.util.isEmpty(result) && result.refreshYn === "Y") {                      
                        // 조회
                    } 
                } else if (columnId === "button2") {

                }
            };

            scwin.btn_basic_onclick = async function (e) {

                const params = {};
                params.formCd = dma_search.get("formCd");
                params.formVer = dma_search.get("formVer");

                const url_ ="/ui/TMS/ULDTMS03040.xml";
                const options = {
                    id: "ULDTMS03040_POP",
                    popupName: "기본문서정보 변경",
                    width: 1100, 
                    height: 640,
                    frameModal: "top"
                };

                const result = await $c.win.openPopup(url_, options, params);
                if (!$c.util.isEmpty(result) && result.refreshYn === "Y") {
                    scwin.fnSearch();
                }                
            };

            scwin.btn_subList_onclick = async function (e) {

                let url_ = "";
                let listType_ = "";
                // 버튼에 따른 팝업 처리
                if (!$c.util.isEmpty(e)) {

                    let options = {};
                    options.width = "760";
                    options.height = "460";

                    const id_ = e.target?.id;
                    if (id_.indexOf("btn_subList2") > -1) {
                        dma_search.set("ldMktTpCd", "");
                        options.popupName = "서식처리절차 변경";
                        options.id = "ULDTMS03050_POP";
                        url_ = "/ui/TMS/ULDTMS03050.xml";
                        listType_ = "2";
                    } else if (id_.indexOf("btn_subList3") > -1) {
                        dma_search.set("ldMktTpCd", "");
                        options.popupName = "서식별 권한그룹정보 변경";
                        options.id = "ULDTMS03060_POP";
                        url_ = "/ui/TMS/ULDTMS03060.xml";
                        listType_ = "3";
                    } else if (id_.indexOf("btn_subList4") > -1) {
                        dma_search.set("ldMktTpCd", "");
                        options.popupName = "공시승인부서정보 변경";
                        options.id = "ULDTMS03070_POP";
                        url_ = "/ui/TMS/ULDTMS03070.xml";
                        listType_ = "4";
                    } else if (id_.indexOf("btn_subList5") > -1) {
                        dma_search.set("ldMktTpCd", "");
                        options.popupName = "첨부문서정보 변경";
                        options.id = "ULDTMS03080_POP";
                        url_ = "/ui/TMS/ULDTMS03080.xml";
                        listType_ = "5";
                    } else if (id_.indexOf("btn_subList6") > -1) {
                        dma_search.set("ldMktTpCd", "");                        
                        options.popupName = "단위서식 변경";
                        options.id = "ULDTMS03090_POP";
                        url_ = "/ui/TMS/ULDTMS03090.xml";
                        listType_ = "6";
                    } else if (id_.indexOf("btn_subList7") > -1) {
                        dma_search.set("ldMktTpCd", "");
                        options.popupName = "편집기분류정보 변경";
                        options.id = "ULDTMS03100_POP";
                        url_ = "/ui/TMS/ULDTMS03100.xml";
                        listType_ = "7";
                    } else if (id_.indexOf("btn_subList8") > -1) {
                        dma_search.set("ldMktTpCd", "");
                        options.popupName = "공시유형분류정보 변경";
                        options.id = "ULDTMS03110_POP";                        
                        url_ = "/ui/TMS/ULDTMS03110.xml";
                        listType_ = "8";
                    } else if (id_.indexOf("btn_subList9") > -1) {  
                        dma_search.set("ldMktTpCd", "9");                      
                        options.popupName = "공시조회유형정보 변경";
                        options.id = "ULDTMS03115_POP";                        
                        url_ = "/ui/TMS/ULDTMS03115.xml";
                        listType_ = "9";                        
                    }

                    let params = {};
                    params.formCd = dma_search.get("formCd");
                    params.formVer = dma_search.get("formVer");
                    params.directYn = "N";

                    const result = await $c.win.openPopup(url_, options, params);
                    if (!$c.util.isEmpty(result) && result.refreshYn === "Y") {                                           
                        // 리스트 조회
                        scwin.fnSubList("N", listType_);
                    }
                }
            };

///////// 4. 서브미션 콜백 영역 /////////
            scwin.sbm_detail_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    // 서식코드
                    if (dma_result.get("repFormVerYn") === "Y" && dma_result.get("endDd") < $c.date.getServerDateTime("yyyyMMdd")) {
                        tbx_formCd.show();
                    } else {
                        tbx_formCd.hide();
                    } 

                    // 서식 버전                    
                    if (!$c.util.isEmpty(dma_result.get("formVer"))) {
                        sbx_formVer.setValue($c.num.parseFloat(dma_result.get("formVer")));
                    }

                    // 영문서식 코드
                    if (dma_result.get("engFormYn") === "Y") {
                        tbx_engFormCd.setValue(dma_result.get("engFormCd") + " 영문 작성여부 : 가능");    
                    } else {
                        tbx_engFormCd.setValue(dma_result.get("engFormCd") + " 영문 작성여부 : 불가능");    
                    }

                    let display_ = "";
                    let totYn_ = "";
                    // 서식첨부 구분 타이틀
                    if (dma_result.get("wrtrptMaindocTpCd") === "1") {
                        tbx_title.setValue("상장신청서구분");

                        if (dma_result.get("listFormYn") === "Y") {
                            tbx_listForm.setValue("상장");
                        } else {
                            tbx_listForm.setValue("공시");
                        }

                        // 공시 제목 변경 가능
                        if (dma_result.get("disclsTitleChgPosblYn") === "Y") {
                            tbx_disclsTitleChgPosblYn.setValue("가능");
                        } else {
                            tbx_disclsTitleChgPosblYn.setValue("불가능");
                        }

                        display_ = "display:block";
                        totYn_ = "Y";                        
                    } else {
                        tbx_title.setValue("공시비공시구분");

                        if (dma_result.get("listFormYn") === "Y") {
                            tbx_listForm.setValue("비공시");
                        } else {
                            tbx_listForm.setValue("공시");
                        }
                        grp_info1.setStyle("display", "none");
                        grp_info4.setStyle("display", "none");

                        display_ = "display:none";
                        totYn_ = "N";
                    }

                    const formUpclssCd = dma_result.get("formUpclssCd");
                    const rsnClssCd = dma_result.get("rsnClssCd");
                    if ((formUpclssCd === "01" && rsnClssCd === "040") ||
                        (formUpclssCd === "01" && rsnClssCd === "041") ||
                        (formUpclssCd === "09" && rsnClssCd === "006") ||
                        (formUpclssCd === "09" && rsnClssCd === "009")) {                        
                        if (dma_result.get("inqdisclsTpCd") !== "A") {                                                        
                            grp_info3.setStyle("display", "none");
                        }
                    } else {
                        grp_info2.setStyle("display", "none");
                        grp_info3.setStyle("display", "none");
                    }

                    // 대표서식버전 여부 
                    if (dma_result.get("repFormVerYn") === "Y") {
                        tbx_repFormVerYn.setValue("예");
                    } else {
                        tbx_repFormVerYn.setValue("아니요");
                    }

                    // 동시사용 여부 
                    if (dma_result.get("oldFormVerUseYn") === "Y") {
                        tbx_oldFormVerUseYn.setValue("사용");
                    } else {
                        tbx_oldFormVerUseYn.setValue("미사용");
                    } 

                    // 아코디언 처리
                    scwin.fnAccrodianProc(display_);
                    // 리스트 조회
                    scwin.fnSubList(totYn_);
                } else {
                    $c.win.alert(result.message);
                }
            };

            scwin.sbm_list_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (!result.success) {
                    $c.win.alert(result.message);
                }
            };

///////// 5. 일반/업무 함수 영역 /////////
            scwin.fnSearch = function () {

                $c.sbm.execute(sbm_detail, dma_search.getJSON());	
            };

            scwin.fnSubList = function (totalYn, listType) {

                // 상세 조회 처리
                const params = {};
                const data = dma_search.getJSON();
                for (let key in data) {                  
                    if (data[key] !== "") {
                        params[key] = data[key];
                    }
                };
                params["totalYn"] = totalYn;
                params["listType"] = listType;                

                $c.sbm.execute(sbm_list, params);                
            };

// 아코디언 처리
            scwin.fnAccrodianProc = function (display_) {

                const obj_ = acd_contents;
                if (obj_ !== null && obj_.panelInfoArr !== null && obj_.panelInfoArr.length >= 6) {
                    document.getElementById(obj_.panelInfoArr[3].id).style = display_;
                    document.getElementById(obj_.panelInfoArr[4].id).style = display_;
                    document.getElementById(obj_.panelInfoArr[5].id).style = display_;
                }
            };
